#include <stdio.h>

/* teste do desafio saudacao-nome — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   A captura do stdout acontece DENTRO do teste: freopen manda o stdout
   para o arquivo temporario, o teste chama a funcao do aluno e le o
   arquivo de volta (fflush, nunca fclose no stdout). */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void saudacaoNome(void);

SM_TEST(as_duas_linhas_com_o_nome) {
    freopen("sm_saida.tmp", "w", stdout);
    saudacaoNome();
    fflush(stdout);

    FILE *f = fopen("sm_saida.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a primeira linha da saudacao", linha, "oi, Ana!\n",
              "o %s troca o buraco pelas letras da caixa, ate o terminador");
    fgets(linha, 80, f);
    checa_str("a segunda linha da saudacao", linha, "seja bem-vinda, Ana!\n",
              "a mesma caixa serve as duas linhas: o nome fica guardado nela");
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "a saida acaba na segunda linha: nenhuma linha extra e aceita");
    fclose(f);
}

